import { describe, expect, it } from "vitest";
import { type Node } from "reactflow";
import { findFocusNode } from "./canvas";

describe("findFocusNode", () => {
  const makeFocusNode = (id: string, selected: boolean): Node => ({
    id,
    selected,
    position: { x: 0, y: 0 },
    data: {},
  });

  it("returns the active node when all trail nodes are selected", () => {
    const nodes = [
      makeFocusNode("START", true),
      makeFocusNode("step-1", true),
      makeFocusNode("step-2", true),
      makeFocusNode("step-3", true),
    ];

    expect(findFocusNode(nodes, "step-1")?.id).toBe("step-1");
  });

  it("falls back to findLast selected when activeNodeId is null", () => {
    const nodes = [
      makeFocusNode("START", true),
      makeFocusNode("step-1", true),
      makeFocusNode("step-3", true),
    ];

    expect(findFocusNode(nodes, null)?.id).toBe("step-3");
  });

  it("returns null when activeNodeId is not in nodes", () => {
    const nodes = [makeFocusNode("step-1", true)];

    expect(findFocusNode(nodes, "missing-step")).toBeNull();
  });
});
